type EmailJsErrorLike = {
  status?: number;
  text?: string;
};

function isEmailJsError(error: unknown): error is EmailJsErrorLike {
  return typeof error === "object" && error !== null;
}

export function getEmailJsErrorMessage(error: unknown) {
  if (!isEmailJsError(error)) {
    return null;
  }

  const parts = [error.status, error.text].filter(Boolean);
  return parts.length > 0 ? parts.join(" ") : null;
}

export function logEmailJsError(context: string, error: unknown) {
  const details = getEmailJsErrorMessage(error);

  if (details) {
    console.error(`${context}: ${details}`, error);
    return;
  }

  console.error(context, error);
}
