type EmailJsConfig = {
  serviceId: string;
  templateId: string;
  publicKey: string;
};

function getTemplateId(templateIdEnvName: string) {
  switch (templateIdEnvName) {
    case "GATSBY_EMAILJS_TEMPLATE_ID":
      return process.env.GATSBY_EMAILJS_TEMPLATE_ID;
    case "GATSBY_EMAILJS_CONTACT_TEMPLATE_ID":
      return process.env.GATSBY_EMAILJS_CONTACT_TEMPLATE_ID;
    default:
      return undefined;
  }
}

export function getEmailJsConfig(templateIdEnvName: string): EmailJsConfig | null {
  const serviceId = process.env.GATSBY_EMAILJS_SERVICE_ID;
  const templateId = getTemplateId(templateIdEnvName);
  const publicKey = process.env.GATSBY_EMAILJS_PUBLIC_KEY;

  if (!serviceId || !templateId || !publicKey) {
    return null;
  }

  return {
    serviceId,
    templateId,
    publicKey,
  };
}
