const RECAPTCHA_SCRIPT_ID = "google-recaptcha-v3";
const RECAPTCHA_SITE_KEY_ENV = "GATSBY_RECAPTCHA_V3_SITE_KEY";

let scriptLoadPromise: Promise<void> | null = null;

declare global {
  interface Window {
    grecaptcha?: {
      ready: (callback: () => void) => void;
      execute: (
        siteKey: string,
        options: {
          action: string;
        },
      ) => Promise<string>;
    };
  }
}

function getSiteKey() {
  if (RECAPTCHA_SITE_KEY_ENV !== "GATSBY_RECAPTCHA_V3_SITE_KEY") {
    return undefined;
  }

  return process.env.GATSBY_RECAPTCHA_V3_SITE_KEY;
}

function loadRecaptchaScript(siteKey: string) {
  if (typeof window === "undefined" || typeof document === "undefined") {
    return Promise.reject(new Error("RECAPTCHA_UNAVAILABLE"));
  }

  if (window.grecaptcha) {
    return Promise.resolve();
  }

  if (scriptLoadPromise) {
    return scriptLoadPromise;
  }

  scriptLoadPromise = new Promise<void>((resolve, reject) => {
    const existingScript = document.getElementById(RECAPTCHA_SCRIPT_ID);

    if (existingScript) {
      existingScript.addEventListener("load", () => resolve(), { once: true });
      existingScript.addEventListener(
        "error",
        () => reject(new Error("RECAPTCHA_LOAD_FAILED")),
        { once: true },
      );
      return;
    }

    const script = document.createElement("script");
    script.id = RECAPTCHA_SCRIPT_ID;
    script.src = `https://www.google.com/recaptcha/api.js?render=${siteKey}`;
    script.async = true;
    script.defer = true;
    script.onload = () => resolve();
    script.onerror = () => reject(new Error("RECAPTCHA_LOAD_FAILED"));

    document.head.appendChild(script);
  }).catch((error) => {
    scriptLoadPromise = null;
    throw error;
  });

  return scriptLoadPromise;
}

export async function executeRecaptchaV3(action: string) {
  const siteKey = getSiteKey();

  if (!siteKey) {
    throw new Error("RECAPTCHA_NOT_CONFIGURED");
  }

  await loadRecaptchaScript(siteKey);

  if (!window.grecaptcha) {
    throw new Error("RECAPTCHA_UNAVAILABLE");
  }

  return new Promise<string>((resolve, reject) => {
    window.grecaptcha?.ready(() => {
      window.grecaptcha
        ?.execute(siteKey, { action })
        .then((token) => {
          if (!token) {
            reject(new Error("RECAPTCHA_EXECUTION_FAILED"));
            return;
          }

          resolve(token);
        })
        .catch(() => reject(new Error("RECAPTCHA_EXECUTION_FAILED")));
    });
  });
}
